UPDATE crm_complaint_policy SET enabled=#{enabled},fallback_recipient_user_id=#{fallbackRecipientUserId,jdbcType=BIGINT},
  empathy_script=#{empathyScript},updated_at=CURRENT_TIMESTAMP(3),version=version+1
WHERE tenant_id=#{tenantId} AND version=#{version}

mapper.select:
SELECT h.* FROM (
  SELECT  FROM crm_complaint_hit WHERE tenant_id=#{q.tenantId}
) h JOIN crm_customer c ON c.tenant_id=h.tenantId AND c.id=h.customerId AND c.deleted=0
WHERE h.tenantId=#{q.tenantId} AND 
AND h.status=#{q.status}
AND h.routingStatus=#{q.routingStatus}

  AND (h.keywordSnapshot LIKE CONCAT('%',#{q.keyword},'%') OR h.evidenceMasked LIKE CONCAT('%',#{q.keyword},'%')
    OR c.customer_no LIKE CONCAT('%',#{q.keyword},'%'))

ORDER BY h.createdAt DESC,h.id DESC LIMIT #{q.size} OFFSET #{q.offset}

SELECT COUNT(*) FROM crm_complaint_hit h JOIN crm_customer c ON c.tenant_id=h.tenant_id AND c.id=h.customer_id AND c.deleted=0
WHERE h.tenant_id=#{q.tenantId} AND 
AND h.status=#{q.status}
AND h.routing_status=#{q.routingStatus}

  AND (h.keyword_snapshot LIKE CONCAT('%',#{q.keyword},'%') OR h.evidence_masked LIKE CONCAT('%',#{q.keyword},'%')
    OR c.customer_no LIKE CONCAT('%',#{q.keyword},'%'))

SELECT cc.* FROM (
  SELECT  FROM crm_complaint_case WHERE tenant_id=#{q.tenantId}
) cc JOIN crm_customer c ON c.tenant_id=cc.tenantId AND c.id=cc.customerId AND c.deleted=0
JOIN crm_complaint_hit h ON h.tenant_id=cc.tenantId AND h.id=cc.complaintHitId
WHERE cc.tenantId=#{q.tenantId} AND 
AND cc.status=#{q.status}

  AND (cc.complaintCaseNo LIKE CONCAT('%',#{q.keyword},'%') OR h.keyword_snapshot LIKE CONCAT('%',#{q.keyword},'%')
    OR cc.resolutionMasked LIKE CONCAT('%',#{q.keyword},'%') OR c.customer_no LIKE CONCAT('%',#{q.keyword},'%'))

ORDER BY cc.createdAt DESC,cc.id DESC LIMIT #{q.size} OFFSET #{q.offset}

SELECT 
FROM crm_complaint_case cc
JOIN crm_customer c ON c.tenant_id=cc.tenant_id AND c.id=cc.customer_id AND c.deleted=0
WHERE cc.tenant_id=#{q.tenantId}
  AND cc.customer_id=#{q.customerId}
  AND 


      AND cc.created_at <= #{q.cursorOccurredAt}


      AND (cc.created_at < #{q.cursorOccurredAt}
           OR (cc.created_at = #{q.cursorOccurredAt} AND cc.id < #{q.cursorSourceId}))


      AND cc.created_at < #{q.cursorOccurredAt}



ORDER BY cc.created_at DESC, cc.id DESC
LIMIT #{q.limit}
